// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address newOwner = address(0xdead);
        address caller = address(this); // owner initially is address(this) from constructor
        // Call setOwner with newOwner from the owner (msg.sender = caller = address(this))
        c.setOwner(newOwner);
        // Reference: owner becomes newOwner (0xdead)
        // Buggy: owner becomes msg.sender (address(this))
        assertTrue(c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a fresh address to call setOwner
        address alice = address(0x123);
        vm.prank(alice);
        // Call setOwner, expected to succeed in reference but revert in bug
        bool ok;
        try c.setOwner(alice) { ok = true; } catch { ok = false; }
        // Reference: setOwner succeeds (ok = true) and owner becomes alice
        // Bug: setOwner reverts (ok = false) and owner stays as this (the deployer)
        assertTrue(ok);
    }
}

