pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // set up a new owner address
        address newOwner = address(0x1234);
        // call setOwner as the current owner (owner from constructor)
        vm.prank(c.owner());
        c.setOwner(newOwner);
        // In reference, c.owner() returns newOwner; in mutant, it returns 0x0000000000000000000000000000000000000001
        assertTrue(c.owner() == newOwner);
    }
}
